 nb.code("import hashlib,json,math,numpy as np", "from pathlib import Path", "def sha(path):\n with Path(path).open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()", "receipts=0", "for line in (PACKET/'SHA256SUMS.txt').read_text().splitlines():\n digest,name=line.split('  ',1);path=PACKET/name\n assert not path.is_symlink() and path.resolve().is_relative_to(PACKET.resolve())\n assert sha(path)==digest,name\n receipts+=1", "inputs=json.loads((PACKET/'input_manifest.json').read_text())", "for path,digest in inputs.items():assert sha(path)==digest,path", "report=json.loads((ROOT/'starplast/data/functional_agreement.json').read_text())", "state=json.loads((PACKET/'uncertainty.json').read_text())", "arrays=np.load(PACKET/'draws.npz')", "assert state['entities']==152 and state['recorded_groups']==145", "assert sum(not row['training_supported'] for row in report['rows'])==4", "assert state['group_order']==sorted({row['group'] for row in report['rows']})", "by_group={group:[row for row in report['rows'] if row['group']==group] for group in state['group_order']}", "manual=[]", "for i,draw in enumerate(arrays['selections']):\n rows=[row for g in draw for row in by_group[state['group_order'][int(g)]]]\n calls=[(r['left_prediction'],r['right_prediction'],r['truth']) for r in rows]\n joint=sum(x is not None and y is not None for x,y,t in calls)\n agree=sum(x is not None and x==y for x,y,t in calls)\n recovered=sum(x==y==t for x,y,t in calls)\n wrong=sum(x is not None and y is not None and x!=t and y!=t for x,y,t in calls)\n delta=sum(y==t for x,y,t in calls)-sum(x==t for x,y,t in calls)\n numerators=[joint,agree,recovered,recovered,wrong,delta]\n denominators=[len(rows),joint,agree,len(rows),joint,len(rows)]\n assert arrays['numerators'][i].tolist()==numerators\n assert arrays['denominators'][i].tolist()==denominators\n values=[n/d if d else float('nan') for n,d in zip(numerators,denominators)]\n np.testing.assert_array_equal(arrays['ratios'][i],values)\n manual.append(values)", "names=['joint_coverage','agreement_among_joint_calls','source_recovery_among_agreements','correct_agreements_all_eligible','shared_wrong_among_joint_calls','right_minus_left_recovery_all_eligible']", "for i,name in enumerate(names):\n values=sorted(row[i] for row in manual if math.isfinite(row[i]))\n bounds=[]\n for q in (.025,.975):\n  rank=(len(values)-1)*q;lo=math.floor(rank);hi=math.ceil(rank);weight=rank-lo\n  difference=values[hi]-values[lo]\n  bounds.append(values[hi]-difference*(1-weight) if weight>=.5 else values[lo]+difference*weight)\n assert bounds==state['rates'][name]['interval'],name\n assert len(values)==state['rates'][name]['valid_draws']\n assert 500-len(values)==state['rates'][name]['undefined_draws']", "export=json.loads((PACKET/'scorecard.json').read_text())['snapshot']", "assert export['counts']==report['counts'] and export['rates']==report['rates']", "assert export['group_uncertainty']==state", "assert export['calibrated_confidence'] is None and export['biological_admission'] is False", "result={'outputs_verified':receipts,'current_inputs_verified':len(inputs),'all500draw_counts_ratios_and_six_intervals_reproduced_exactly':True,'genes':152,'unsupported':4,'recorded_groups':145,'draws':500,'agreement_recovery_interval':state['rates']['source_recovery_among_agreements']['interval'],'shared_wrong_interval':state['rates']['shared_wrong_among_joint_calls']['interval'],'right_minus_left_recovery_interval':state['rates']['right_minus_left_recovery_all_eligible']['interval'],'fits_performed':0,'biological_admission':False}", "(OUT/'acceptance.json').write_text(json.dumps(result,indent=2)+'\\n')", "result")
